param([Parameter(Mandatory=$true)][string]$HostClientFolder)
$ErrorActionPreference = 'Stop'
# Copy ONLY the public connection files generated by the running host.
$source = (Resolve-Path -LiteralPath $HostClientFolder).Path
$internet = Join-Path $source 'internet.json'
$certificate = Join-Path $source 'server-certificate.pem'
$config = Get-Content -LiteralPath $internet -Raw | ConvertFrom-Json
if (-not $config.login.issuer.StartsWith('https://') -or -not $config.servers.Count) { throw 'Invalid host client configuration.' }
$pem = Get-Content -LiteralPath $certificate -Raw
if (-not $pem.Contains('BEGIN CERTIFICATE') -or $pem.Contains('PRIVATE KEY')) { throw 'Expected the public server certificate only.' }
$zip = Join-Path (Split-Path -Parent $PSScriptRoot) 'ShippingLanes-Friends-Ready.zip'
if (Test-Path -LiteralPath $zip) { throw 'A friends ZIP already exists. Preserve or rename it before preparing another.' }
foreach ($name in @('internet.json', 'server-certificate.pem')) {
    Copy-Item -LiteralPath (Join-Path $source $name) -Destination (Join-Path $PSScriptRoot $name)
}
$names = @('Game', 'Licenses', 'internet.json', 'server-certificate.pem', 'Launch-Client.cmd', 'Launch-Client.ps1', 'README-FRIENDS.md')
$paths = $names | ForEach-Object { Join-Path $PSScriptRoot $_ }
# Explicit allowlist excludes PlayerData, credentials, private keys and host saves.
Compress-Archive -LiteralPath $paths -DestinationPath $zip -CompressionLevel Optimal
Write-Output "Friends package created: $zip"
Write-Output 'Test internet sign-in and gameplay from outside your home before sharing. Give each friend a separate enrolled account.'
